{"content": "1|// Loop sonoro de la portada (Web Audio API, sin dependencias).
2|// El año suena como una pieza en bucle: cada mes son `barsPerMonth` compases de `barSeconds` segundos.
3|// En cada compás, la página entrega la lista de cantos a tocar (plan): { hits: [{ url, gain, pan, seed, win }], tick }.
4|// `win`: inicios (s) de los mejores tramos del clip; cada copia toca uno de ellos.
5|// Cada «hit» es un fragmento de la grabación de una especie que entra en un momento al azar del compás;
6|// una especie con 4 copias suena 4 veces en el mismo compás.
7|// Los navegadores no dejan sonar audio sin un gesto del usuario: el AudioContext se crea al cargar, pero
8|// queda suspendido hasta el primer clic o tecla (unlock).
9|
10|const SoundLoop = (() => {
11|  const LOOKAHEAD = 0.3;
12|  const SEGMENT = 2.0; // segundos de canto por copia, como máximo
13|  let ctx = null;
14|  let master = null;
15|  let timer = null;
16|  let raf = null;
17|  let barSeconds = 3;
18|  let barsPerMonth = 4;
19|  let nextTime = 0;
20|  let month = 0;
21|  let bar = 0;
22|  let plan = null;
23|  let onBar = null;
24|  let muted = false;
25|  const buffers = new Map();
26|  const queue = [];
27|
28|  function ensure() {
29|    if (ctx) return ctx;
30|    const AC = window.AudioContext || window.webkitAudioContext;
31|    if (!AC) return null;
32|    ctx = new AC();
33|    const comp = ctx.createDynamicsCompressor();
34|    comp.threshold.value = -18;
35|    comp.ratio.value = 4;
36|    master = ctx.createGain();
37|    master.gain.value = muted ? 0 : 0.85;
38|    master.connect(comp).connect(ctx.destination);
39|    return ctx;
40|  }
41|
42|  function load(urls) {
43|    if (!ensure()) return Promise.resolve();
44|    return Promise.all(
45|      urls.filter((u) => u && !buffers.has(u)).map(async (url) => {
46|        buffers.set(url, null); // evita cargas duplicadas
47|        try {
48|          const data = await fetch(url).then((r) => r.arrayBuffer());
49|          buffers.set(url, await ctx.decodeAudioData(data));
50|        } catch (err) {
51|          buffers.delete(url);
52|          console.warn("No se pudo cargar", url, err);
53|        }
54|      }),
55|    );
56|  }
57|
58|  // Generador pseudoaleatorio con semilla: el mismo compás suena igual en cada vuelta del año.
59|  function seeded(seed) {
60|    let t = seed + 0x6d2b79f5;
61|    return () => {
62|      t = Math.imul(t ^ (t >>> 15), t | 1);
63|      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
64|      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
65|    };
66|  }
67|
68|  function hit(time, { url, gain, pan, seed, win }) {
69|    const buffer = buffers.get(url);
70|    if (!buffer) return; // aún cargando: ese compás suena sin esta copia
71|    const rand = seeded(seed);
72|    const len = Math.min(SEGMENT, buffer.duration);
73|    // Desde uno de los mejores tramos del clip (análisis previo), no desde un punto al azar:
74|    // así no suena un pedazo de puro fondo entre dos cantos.
75|    const pick = win && win.length ? win[Math.floor(rand() * win.length)] : rand() * Math.max(0, buffer.duration - len);
76|    const offset = Math.min(pick, Math.max(0, buffer.duration - len));
77|    const at = time + rand() * Math.max(0.05, barSeconds - len * 0.6);
78|    const src = ctx.createBufferSource();
79|    src.buffer = buffer;
80|    const env = ctx.createGain();
81|    env.gain.setValueAtTime(0.0001, at);
82|    env.gain.exponentialRampToValueAtTime(gain, at + 0.06);
83|    env.gain.setValueAtTime(gain, at + len * 0.6);
84|    env.gain.exponentialRampToValueAtTime(0.0001, at + len);
85|    const panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
86|    src.connect(env);
87|    if (panner) {
88|      panner.pan.value = pan;
89|      env.connect(panner).connect(master);
90|    } else env.connect(master);
91|    src.start(at, offset, len + 0.05);
92|  }
93|
94|  // Inicio de mes: golpe grave y suave, para que se oigan los «compases» del año.
95|  function tick(time) {
96|    const osc = ctx.createOscillator();
97|    osc.type = "sine";
98|    osc.frequency.setValueAtTime(130, time);
99|    osc.frequency.exponentialRampToValueAtTime(65, time + 0.15);
100|    const g = ctx.createGain();
101|    g.gain.setValueAtTime(0.0001, time);
102|    g.gain.exponentialRampToValueAtTime(0.16, time + 0.006);
103|    g.gain.exponentialRampToValueAtTime(0.0001, time + 0.25);
104|    osc.connect(g).connect(master);
105|    osc.start(time);
106|    osc.stop(time + 0.3);
107|  }
108|
109|  function schedule() {
110|    // Suspendido (sin gesto del usuario): no se agenda nada; al reanudar, el año parte desde aquí.
111|    if (ctx.state !== "running") {
112|      nextTime = ctx.currentTime + 0.1;
113|      return;
114|    }
115|    while (nextTime < ctx.currentTime + LOOKAHEAD) {
116|      const p = plan(month, bar) || {};
117|      if (p.tick) tick(nextTime);
118|      (p.hits || []).forEach((h) => hit(nextTime, h));
119|      queue.push({ month, bar, time: nextTime });
120|      nextTime += barSeconds;
121|      bar += 1;
122|      if (bar >= barsPerMonth) {
123|        bar = 0;
124|        month = (month + 1) % 12;
125|      }
126|    }
127|  }
128|
129|  // Avisa el compás que está sonando (cada cuadro y en el temporizador: rAF se pausa con la pestaña oculta).
130|  function flush() {
131|    while (queue.length && queue[0].time <= ctx.currentTime) {
132|      const item = queue.shift();
133|      if (onBar) onBar(item.month, item.bar);
134|    }
135|  }
136|  function frame() {
137|    flush();
138|    raf = requestAnimationFrame(frame);
139|  }
140|
141|  return {
142|    load,
143|    get playing() {
144|      return timer !== null;
145|    },
146|    // true si el navegador ya deja sonar (hubo un gesto del usuario).
147|    get unlocked() {
148|      return !!ctx && ctx.state === "running";
149|    },
150|    configure(opts) {
151|      barSeconds = opts.barSeconds || barSeconds;
152|      barsPerMonth = opts.barsPerMonth || barsPerMonth;
153|      ensure();
154|    },
155|    async unlock() {
156|      if (!ensure()) return false;
157|      if (ctx.state !== "running") {
158|        try {
159|          await ctx.resume();
160|        } catch (err) {
161|          return false;
162|        }
163|      }
164|      return ctx.state === "running";
165|    },
166|    start(fromMonth, planFn, barFn) {
167|      if (!ensure()) return false;
168|      plan = planFn;
169|      onBar = barFn;
170|      month = fromMonth;
171|      bar = 0;
172|      nextTime = ctx.currentTime + 0.1;
173|      queue.length = 0;
174|      clearInterval(timer);
175|      cancelAnimationFrame(raf);
176|      schedule();
177|      timer = setInterval(() => {
178|        schedule();
179|        flush();
180|      }, 50);
181|      raf = requestAnimationFrame(frame);
182|      return true;
183|    },
184|    // Salta a otro mes en el próximo compás (cuando el usuario elige un mes).
185|    jump(m) {
186|      if (!ctx || timer === null) return;
187|      queue.length = 0;
188|      month = m;
189|      bar = 0;
190|      nextTime = Math.max(ctx.currentTime + 0.05, nextTime - barSeconds); // descarta el compás ya agendado
191|    },
192|    stop() {
193|      clearInterval(timer);
194|      cancelAnimationFrame(raf);
195|      timer = null;
196|      queue.length = 0;
197|    },
198|    setMuted(value) {
199|      muted = value;
200|      if (master) master.gain.setTargetAtTime(value ? 0 : 0.85, ctx.currentTime, 0.05);
201|    },
202|  };
203|})();", "total_lines": 203, "file_size": 6809, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// Sonificación con Web Audio API (sin dependencias).
2|// Un mes = un compás. app.js entrega, por compás, una descripción declarativa:
3|//   { pad:  { freqs: [Hz…], gain },            colchón sostenido (residentes)
4|//     hits: [{ at, sample, rate, gain, pan }],  cantos reales (granos de Xeno-canto)
5|//     tick: true }                              golpe suave que marca el inicio del mes
6|// `at` va de 0 a 1 dentro del compás; `rate` transpone el grano (tono ← latitud).
7|// El AudioContext solo se crea tras un gesto del usuario (clic en Play).
8|
9|const Sonifier = (() => {
10|  const BAR_SECONDS = 2.4;
11|  const GRAIN_SECONDS = 0.9;
12|  // Los cantos se bajan una quinta y se filtran: los granos cortos de cantos agudos (Fío-fío ~4 kHz,
13|  // Picaflor chico ~8 kHz) sonaban como "beeps".
14|  const TRANSPOSE = Math.pow(2, -7 / 12);
15|  const GRAIN_LOWPASS = 3500;
16|  const LOOKAHEAD = 0.2;
17|  let ctx = null;
18|  let master = null;
19|  let timer = null;
20|  let raf = null;
21|  let nextBar = 0;
22|  let month = 0;
23|  let getBar = null;
24|  let onMonth = null;
25|  let muted = false;
26|  const buffers = new Map();
27|  const queue = [];
28|
29|  function ensure() {
30|    if (ctx) return ctx;
31|    const AC = window.AudioContext || window.webkitAudioContext;
32|    if (!AC) return null;
33|    ctx = new AC();
34|    const comp = ctx.createDynamicsCompressor();
35|    comp.threshold.value = -20;
36|    comp.ratio.value = 3;
37|    master = ctx.createGain();
38|    master.gain.value = muted ? 0 : 0.9;
39|    master.connect(comp).connect(ctx.destination);
40|    return ctx;
41|  }
42|
43|  async function load(urls) {
44|    if (!ensure()) return;
45|    await Promise.all(
46|      urls.filter((u) => u && !buffers.has(u)).map(async (url) => {
47|        buffers.set(url, null); // evita cargas duplicadas
48|        try {
49|          const data = await fetch(url).then((r) => r.arrayBuffer());
50|          buffers.set(url, await ctx.decodeAudioData(data));
51|        } catch (err) {
52|          buffers.delete(url);
53|          console.warn("No se pudo cargar", url, err);
54|        }
55|      }),
56|    );
57|  }
58|
59|  // Colchón: dos osciladores suaves por nota con filtro cálido; entra y sale con rampas.
60|  function pad(time, { freqs, gain }) {
61|    if (!freqs || !freqs.length || gain <= 0) return;
62|    const env = ctx.createGain();
63|    env.gain.setValueAtTime(0.0001, time);
64|    env.gain.linearRampToValueAtTime(gain, time + 0.5);
65|    env.gain.setValueAtTime(gain, time + BAR_SECONDS - 0.35);
66|    env.gain.linearRampToValueAtTime(0.0001, time + BAR_SECONDS + 0.25);
67|    const filter = ctx.createBiquadFilter();
68|    filter.type = "lowpass";
69|    filter.frequency.value = 900;
70|    filter.connect(env).connect(master);
71|    freqs.forEach((f, i) => {
72|      for (const [type, detune] of [["sine", 0], ["triangle", i % 2 ? 6 : -6]]) {
73|        const osc = ctx.createOscillator();
74|        osc.type = type;
75|        osc.frequency.value = f;
76|        osc.detune.value = detune;
77|        const g = ctx.createGain();
78|        g.gain.value = type === "sine" ? 0.6 : 0.25;
79|        osc.connect(g).connect(filter);
80|        osc.start(time);
81|        osc.stop(time + BAR_SECONDS + 0.3);
82|      }
83|    });
84|  }
85|
86|  // Grano de canto real. Si el audio no cargó, cae a un pulso sintético.
87|  function hit(time, { sample, rate = 1, gain = 0.3, pan = 0 }) {
88|    const out = ctx.createGain();
89|    const lowpass = ctx.createBiquadFilter();
90|    lowpass.type = "lowpass";
91|    lowpass.frequency.value = GRAIN_LOWPASS;
92|    lowpass.Q.value = 0.5;
93|    lowpass.connect(out);
94|    const panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
95|    if (panner) {
96|      panner.pan.value = pan;
97|      out.connect(panner).connect(master);
98|    } else out.connect(master);
99|    const buffer = buffers.get(sample);
100|    const dur = GRAIN_SECONDS;
101|    const r = rate * TRANSPOSE;
102|    // Envolvente suave: entra en 60 ms y se desvanece en la segunda mitad.
103|    out.gain.setValueAtTime(0.0001, time);
104|    out.gain.exponentialRampToValueAtTime(gain, time + 0.06);
105|    out.gain.setValueAtTime(gain, time + dur * 0.45);
106|    out.gain.exponentialRampToValueAtTime(0.0001, time + dur);
107|    if (buffer) {
108|      const src = ctx.createBufferSource();
109|      src.buffer = buffer;
110|      src.playbackRate.value = r;
111|      src.connect(lowpass);
112|      src.start(time, 0, dur * r + 0.05);
113|    } else {
114|      // Especie sin clip: nota suave y grave en vez de un pitido.
115|      const osc = ctx.createOscillator();
116|      osc.type = "sine";
117|      osc.frequency.value = 330 * rate;
118|      osc.connect(lowpass);
119|      osc.start(time);
120|      osc.stop(time + dur);
121|    }
122|  }
123|
124|  // Marca de mes: golpe grave y corto (tipo tambor apagado), no un clic agudo.
125|  function tick(time) {
126|    const osc = ctx.createOscillator();
127|    osc.type = "sine";
128|    osc.frequency.setValueAtTime(140, time);
129|    osc.frequency.exponentialRampToValueAtTime(70, time + 0.12);
130|    const g = ctx.createGain();
131|    g.gain.setValueAtTime(0.0001, time);
132|    g.gain.exponentialRampToValueAtTime(0.18, time + 0.005);
133|    g.gain.exponentialRampToValueAtTime(0.0001, time + 0.18);
134|    osc.connect(g).connect(master);
135|    osc.start(time);
136|    osc.stop(time + 0.2);
137|  }
138|
139|  function scheduleBar(m, t0) {
140|    const bar = getBar(m) || {};
141|    if (bar.tick) tick(t0);
142|    if (bar.pad) pad(t0, bar.pad);
143|    (bar.hits || []).forEach((h) => hit(t0 + h.at * BAR_SECONDS, h));
144|  }
145|
146|  function schedule() {
147|    while (nextBar < ctx.currentTime + LOOKAHEAD) {
148|      scheduleBar(month, nextBar);
149|      queue.push({ month, time: nextBar });
150|      nextBar += BAR_SECONDS;
151|      month = (month + 1) % 12;
152|    }
153|  }
154|
155|  // Avisa el mes que está sonando. Corre en cada cuadro y también en el temporizador,
156|  // porque requestAnimationFrame se pausa cuando la pestaña no está visible.
157|  function flush() {
158|    while (queue.length && queue[0].time <= ctx.currentTime) {
159|      const item = queue.shift();
160|      if (onMonth) onMonth(item.month);
161|    }
162|  }
163|
164|  function frame() {
165|    flush();
166|    raf = requestAnimationFrame(frame);
167|  }
168|
169|  return {
170|    BAR_SECONDS,
171|    load,
172|    get playing() {
173|      return timer !== null;
174|    },
175|    async start(fromMonth, barFn, monthFn, urls = []) {
176|      if (!ensure()) return false;
177|      if (ctx.state === "suspended") await ctx.resume();
178|      await load(urls);
179|      getBar = barFn;
180|      onMonth = monthFn;
181|      month = fromMonth;
182|      nextBar = ctx.currentTime + 0.08;
183|      queue.length = 0;
184|      schedule();
185|      timer = setInterval(() => {
186|        schedule();
187|        flush();
188|      }, 50);
189|      raf = requestAnimationFrame(frame);
190|      return true;
191|    },
192|    stop() {
193|      clearInterval(timer);
194|      cancelAnimationFrame(raf);
195|      timer = null;
196|      queue.length = 0;
197|    },
198|    setMuted(value) {
199|      muted = value;
200|      if (master) master.gain.setTargetAtTime(value ? 0 : 0.9, ctx.currentTime, 0.05);
201|    },
202|  };
203|})();", "total_lines": 203, "file_size": 6766, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

