408|  // ------------------------------ C2 · una región de cerca
409|  // Selector: Chile acostado (norte a la izquierda), una región por clic.
410|  function drawRegionPicker() {
411|    if (!maps.geo) return;
412|    const host = document.getElementById("region-picker");
413|    host.innerHTML = "";
414|    const w = host.clientWidth;
415|    // Girar 90°: el norte queda a la izquierda y el país se lee de norte a sur. Se ajusta al ancho y el alto
416|    // sigue a la forma, con tope.
417|    const projection = d3.geoMercator().angle(90).fitWidth(w, maps.land);
418|    const path = d3.geoPath(projection);
419|    const h = Math.min(Math.ceil(path.bounds(maps.land)[1][1]) + 14, w < 560 ? 90 : 170);
420|    projection.fitExtent([[0, 0], [w, h - 14]], maps.land);
421|    const [[x0], [x1]] = path.bounds(maps.land);
422|    const svg = d3.select(host).append("svg").attr("viewBox", `0 0 ${w} ${h}`).attr("width", w).attr("height", h)
423|      .attr("role", "group").attr("aria-label", "Elegir región");
424|    svg.selectAll("path").data(maps.land.features).join("path")
