464|  async function loadRegion(id) {
465|    if (!maps.regionCache.has(id)) {
466|      maps.regionCache.set(id, getJSON(`grid_region/${maps.codes.get(id)}.json?v=1`).catch((err) => {
467|        maps.regionCache.delete(id);
468|        throw err;
469|      }));
470|    }
471|    return maps.regionCache.get(id);
472|  }
473|
474|  // Puntos de una celda: n por clase, en posiciones al azar dentro de la celda pero fijas para esa celda y
475|  // clase (el k-ésimo punto cae siempre en el mismo lugar), así de un mes a otro solo aparecen o desaparecen.
476|  function cellDots(cell, ci, counts, perDot, res) {
477|    const dots = [];
478|    counts.forEach((days, cls) => {
479|      const rand = seeded(ci * 7919 + cls * 104729);
480|      const exact = days / perDot;
481|      const n = Math.floor(exact) + (seeded(ci * 31 + cls)() < exact % 1 ? 1 : 0);
482|      for (let k = 0; k < n; k++) dots.push({ cls, lon: cell[0] + rand() * res, lat: cell[1] + rand() * res });
483|    });
484|    return dots;
485|  }
486|
487|  async function drawRegionMaps() {
488|    const id = maps.region;
489|    const host = document.getElementById("region-maps");
490|    let data;
491|    try {
492|      data = await loadRegion(id);
493|    } catch (err) {
494|      console.error(err);
495|      host.textContent = "No se pudieron cargar los datos de la región.";
496|      return;
497|    }
498|    if (id !== maps.region) return; // llegó tarde: ya se eligió otra
499|    const feature = maps.land.features.find((f) => f.properties.id === id);
500|    const cardW = cardWidth(host, 150);
501|    const w = cardW - 16;
502|    const projection = d3.geoMercator().fitWidth(w, feature);
503|    const path = d3.geoPath(projection);
504|    const [[, y0], [, y1]] = path.bounds(feature);
505|    // Alto según la forma de la región, con tope (Chile tiene regiones muy alargadas).
506|    const h = Math.min(Math.ceil(y1 - y0) + 2, 460);
507|    projection.fitSize([w, h], feature);
508|    const r = Math.max(1.1, Math.min(2, w / 150));
509|    const classes = [0, 1, 2];
510|    const cards = buildStrip("region-maps", cardW, h, (svg, m) => {
511|      svg.append("path").attr("class", "land").attr("d", path(feature));
512|      const dots = data.months[m].flatMap(([ci, ...counts]) => cellDots(data.cells[ci], ci, counts, data.perDot, data.res));
513|      // Residentes abajo; visitantes encima (son menos y no deben quedar tapados).
514|      dots.sort((a, b) => a.cls - b.cls);
515|      svg.append("g").selectAll("circle").data(dots).join("circle")
516|        .attr("class", (d) => `dot-r c${d.cls}`)
517|        .attr("cx", (d) => projection([d.lon, d.lat])[0])
518|        .attr("cy", (d) => projection([d.lon, d.lat])[1])
519|        .attr("r", r);
520|    }, `Mapa de ${maps.names.get(id)}`);
521|    // Bajo cada mapa: qué parte de lo registrado son visitantes.
522|    cards.append("p").attr("class", "map-n").html((m) => {
523|      const sums = classes.map((c) => d3.sum(data.months[m], (row) => row[c + 1]));
524|      const total = d3.sum(sums);
525|      if (!total) return "sin datos";
526|      const p = (x) => `${Math.round((100 * x) / total)} %`;
527|      return `<span class="t1">${p(sums[1])} verano</span> · <span class="t2">${p(sums[2])} invierno</span>`;
528|    });
529|    applyResidentToggle();
530|    document.getElementById("region-scale").textContent =
531|      `1 punto ≈ ${data.perDot.toLocaleString("es-CL")} especie-días · celdas de ~5 km`;
532|    updateMaps(false);
533|  }
534|
535|  // Ocultar residentes: deja ver dónde están los nómadas (con residentes, los tapan en zonas muy observadas).
536|  function applyResidentToggle() {
537|    const hide = document.getElementById("hide-residents").checked;
538|    d3.select("#region-maps").classed("no-residents", hide);
539|  }
540|
541|  // ------------------------------ comunes a las dos franjas
542|  function updateMaps(follow) {
543|    for (const { id, cards } of strips) {
544|      if (!cards) continue;
545|      cards.classed("current", (m) => m === state.month);
546|      if (!follow) continue;
547|      // Si el mes actual no está a la vista, se desplaza la franja (no la página).
548|      const strip = document.getElementById(id);
549|      const card = cards.filter((m) => m === state.month).node();
550|      if (!card) continue;
551|      const w = card.offsetWidth;
552|      const i = AUSTRAL.indexOf(state.month);
553|      if (i * w < strip.scrollLeft || (i + 1) * w > strip.scrollLeft + strip.clientWidth) {
554|        const perPage = Math.max(1, Math.round(strip.clientWidth / w));
555|        strip.scrollTo({ left: Math.floor(i / perPage) * perPage * w, behavior: "smooth" });
556|      }
557|    }
558|  }
559|
560|  function initStripNav(id) {
561|    const strip = document.getElementById(id);
562|    const page = (dir) => {
563|      const card = strip.querySelector(".map-card");
564|      const w = card ? card.offsetWidth : strip.clientWidth / 4;
565|      strip.scrollBy({ left: dir * Math.round(strip.clientWidth / w) * w, behavior: "smooth" });
566|    };
567|    document.querySelectorAll(`[data-strip="${id}"]`).forEach((b) =>
568|      b.addEventListener("click", () => page(b.dataset.dir === "prev" ? -1 : 1)));
569|  }
570|  function initMapsNav() {
571|    initStripNav("maps");
572|    initStripNav("region-maps");
573|    initMapsMode();
574|    document.getElementById("hide-residents").addEventListener("change", applyResidentToggle);
575|  }
