578|    drawRegionPicker();
579|    drawRegionMaps();
580|  }
581|
582|  // ---------------------------------------------------------------- tabla (vista accesible)
583|  function drawTable() {
584|    const rows = AUSTRAL.map((m) => `<tr><th scope="row">${MONTHS[m]}</th>${D.months[m].map((v) => `<td>${v}</td>`).join("")}</tr>`).join("");
585|    document.getElementById("table").innerHTML =
586|      `<table><thead><tr><th scope="col">Mes</th>${LABEL.map((l) => `<th scope="col">${l}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table>`;
587|  }
588|
589|  // ---------------------------------------------------------------- mes
590|  function drawMonths() {
591|    const host = d3.select("#months");
592|    host.selectAll("button").data(AUSTRAL).join("button")
593|      .attr("type", "button").attr("class", "month")
594|      .attr("aria-label", (m) => MONTHS[m])
595|      .text((m) => MON[m])
596|      .on("click", (event, m) => setMonth(m));
597|    updateMonths();
598|  }
599|  function updateMonths() {
600|    d3.select("#months").selectAll("button").attr("aria-pressed", (m) => String(m === state.month));
601|  }
602|  // fromLoop: el cambio viene del loop sonoro; si no, lo eligió el usuario y el loop salta a ese mes.
603|  function setMonth(m, fromLoop = false) {
604|    state.month = m;
605|    if (!fromLoop) {
606|      SoundLoop.jump(m);
607|      updateNowPlaying(m);
608|    }
609|    updatePulse();
610|    updateFlock(true);
611|    updateMonths();
612|    updateMaps(true);
613|  }
614|
615|  // ---------------------------------------------------------------- sonido: loop del año
616|  // El año suena en bucle (loop.js): cada mes son 4 compases de 3 s. En cada compás suenan fragmentos de cantos
617|  // reales de las especies presentes ese mes en el ámbito elegido (Chile o la región de «Una región de cerca»);
618|  // cuanto más extendida está una especie ese mes, más copias de su canto (1 a 4). Datos: data/loop.json.
619|  // Arranca solo al cargar la página; el navegador lo deja sonar desde el primer clic o tecla.
620|  const PLAY_D = "M4.5 2.5v11l9-5.5z";
621|  const PAUSE_D = "M4 2.5h3v11H4zM9 2.5h3v11H9z";
622|  const sound = { data: null, scope: 0, paused: false, muted: false };
623|  try {
624|    sound.muted = localStorage.getItem("loop-muted") === "1";
625|  } catch (err) { /* sin almacenamiento: queda con sonido */ }
626|
627|  function seeded(seed) {
628|    let t = seed + 0x6d2b79f5;
629|    return () => {
630|      t = Math.imul(t ^ (t >>> 15), t | 1);
631|      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
632|      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
633|    };
634|  }
635|  const voicesFor = (m) => (sound.data.scopes[String(sound.scope)] || sound.data.scopes["0"])[m];
636|  const clipsFor = (m) => voicesFor(m).map(([sid]) => sound.data.species[sid].clip);
637|
638|  function planBar(m, b) {
639|    const voices = voicesFor(m);
640|    const total = d3.sum(voices, (v) => v[1]) || 1;
641|    const hits = [];
642|    voices.forEach(([sid, copies], vi) => {
643|      for (let k = 0; k < copies; k++) {
644|        const seed = (((m * 8 + b) * 32 + vi) * 8 + k) * 31 + sid;
645|        const sp = sound.data.species[sid];
646|        hits.push({ url: sp.clip, win: sp.win, gain: 0.6 / Math.sqrt(total), pan: (seeded(seed)() * 2 - 1) * 0.7, seed: seed * 7 + 3 });
647|      }
648|    });
649|    if (b === 0) SoundLoop.load(clipsFor((m + 1) % 12)); // precarga el mes siguiente
650|    return { tick: b === 0, hits };
651|  }
652|  function onBar(m, b) {
653|    if (m !== state.month) setMonth(m, true);
654|    d3.selectAll("#bars i").classed("on", (d, i) => i === b);
655|    updateNowPlaying(m);
656|  }
657|  function updateNowPlaying(m = state.month) {
658|    if (!sound.data) return;
659|    const names = voicesFor(m).map(([sid, copies]) => {
660|      const sp = sound.data.species[sid];
661|      return `<span class="v c${sp.cls}">${sp.name}${copies > 1 ? ` <b>×${copies}</b>` : ""}</span>`;
662|    });
663|    document.getElementById("now-playing").innerHTML = names.join(" ");
664|  }
665|
666|  async function initSound() {
667|    try {
668|      sound.data = await fetch("data/loop.json?v=2").then((r) => {
669|        if (!r.ok) throw new Error(`loop.json: ${r.status}`);
670|        return r.json();
671|      });
672|    } catch (err) {
673|      console.error(err);
674|      return;
675|    }
676|    SoundLoop.configure(sound.data);
677|    SoundLoop.setMuted(sound.muted);
678|    syncSoundButtons();
679|    updateNowPlaying();
680|    await SoundLoop.load(clipsFor(state.month));
681|    SoundLoop.start(state.month, planBar, onBar);
682|    // Sin gesto del usuario el navegador mantiene el audio suspendido: el loop arranca con el primer clic o tecla.
683|    if (!SoundLoop.unlocked) {
684|      const hint = document.getElementById("sound-hint");
685|      hint.hidden = false;
686|      const unlock = async () => {
687|        if (await SoundLoop.unlock()) {
688|          hint.hidden = true;
689|          removeEventListener("pointerdown", unlock, true);
690|          removeEventListener("keydown", unlock, true);
691|        }
692|      };
693|      addEventListener("pointerdown", unlock, true);
694|      addEventListener("keydown", unlock, true);
695|    }
696|  }
697|
698|  function togglePause() {
699|    if (!sound.data) return;
700|    sound.paused = !sound.paused;
701|    if (sound.paused) SoundLoop.stop();
702|    else SoundLoop.start(state.month, planBar, onBar);
703|    syncSoundButtons();
704|  }
705|  function toggleMute() {
706|    sound.muted = !sound.muted;
707|    SoundLoop.setMuted(sound.muted);
708|    try {
709|      localStorage.setItem("loop-muted", sound.muted ? "1" : "0");
710|    } catch (err) { /* sin almacenamiento */ }
