712|  }
713|  function syncSoundButtons() {
714|    const play = document.getElementById("play");
715|    play.setAttribute("aria-pressed", String(!sound.paused));
716|    play.setAttribute("aria-label", sound.paused ? "Reanudar el año" : "Pausar el año");
717|    play.title = `${sound.paused ? "Reanudar" : "Pausar"} (barra espaciadora)`;
718|    document.getElementById("play-icon").setAttribute("d", sound.paused ? PLAY_D : PAUSE_D);
719|    const mute = document.getElementById("mute");
