721|    mute.setAttribute("aria-label", sound.muted ? "Activar sonido" : "Silenciar");
722|    mute.title = sound.muted ? "Activar sonido" : "Silenciar";
723|    d3.selectAll("#sound-scope button").attr("aria-pressed", function () {
724|      return String((this.dataset.scope === "region") === (sound.scope !== 0));
725|    });
726|  }
